import{_ as r,o as l,c as t,a2 as o}from"./chunks/framework.BV21bweQ.js";const c=JSON.parse('{"title":"初代变化神","description":"","frontmatter":{},"headers":[],"relativePath":"底层/人物/初代变化神.md","filePath":"底层/人物/初代变化神.md","lastUpdated":1787066340000}'),i={name:"底层/人物/初代变化神.md"};function n(e,a,s,h,g,d){return l(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="初代变化神" tabindex="-1">初代变化神 <a class="header-anchor" href="#初代变化神" aria-label="Permalink to &quot;初代变化神&quot;">​</a></h1><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><ul><li><strong>名称</strong>：作为人类无固定姓名，通常称为&quot;初代变化神&quot;</li><li><strong>身份</strong>：初代变化神，现实世界的完善者</li><li><strong>种族</strong>：人类</li><li><strong>时代</strong>：从人类原始社会至前传超算纪元</li><li><strong>所处空间</strong>：基底层（自我禁锢）</li><li><strong>状态</strong>：意识在基底层中自我禁锢，监管上位变化神权</li></ul><h2 id="角色概述" tabindex="-1">角色概述 <a class="header-anchor" href="#角色概述" aria-label="Permalink to &quot;角色概述&quot;">​</a></h2><p>初代变化神是变化神权的初代载体，也是现实世界的重要完善者。他作为人类从原始社会时期开始就承载着变化神权，伴随着人类走完了整个文明史。在此期间不断探索宇宙与自身，并深入探究过基底层，了解了神权的相关知识。</p><p>作为神权体系的命名者和规则制定者，初代变化神深刻认识到神权的危险性以及现实世界被基底层日益侵入的状况，最终许下宏愿制定了神权使用的基本规则，并将现实世界在四维空间上进行了闭环。</p><h2 id="起源与早期活动" tabindex="-1">起源与早期活动 <a class="header-anchor" href="#起源与早期活动" aria-label="Permalink to &quot;起源与早期活动&quot;">​</a></h2><h3 id="神权获得" tabindex="-1">神权获得 <a class="header-anchor" href="#神权获得" aria-label="Permalink to &quot;神权获得&quot;">​</a></h3><ul><li><strong>进入时机</strong>：现实世界尚未封闭时，变化神权从边缘渗入现实世界</li><li><strong>寻找载体</strong>：变化神权寻找到了原始社会时期的人类作为载体</li></ul><h3 id="文明伴随" tabindex="-1">文明伴随 <a class="header-anchor" href="#文明伴随" aria-label="Permalink to &quot;文明伴随&quot;">​</a></h3><p>初代变化神伴随着人类走完了整个文明史：</p><ul><li><strong>长期观察</strong>：在漫长的人类文明发展中观察和学习</li><li><strong>自我探究</strong>：在此期间不断探索宇宙与自身本质</li><li><strong>基底层研究</strong>：深入探究过基底层，初步了解了神权的相关知识</li><li><strong>神权预测</strong>：根据自身神权的性质对可能存在的创造神、毁灭神做出了预测</li></ul><h2 id="宏愿与重要贡献" tabindex="-1">宏愿与重要贡献 <a class="header-anchor" href="#宏愿与重要贡献" aria-label="Permalink to &quot;宏愿与重要贡献&quot;">​</a></h2><h3 id="宏愿背景" tabindex="-1">宏愿背景 <a class="header-anchor" href="#宏愿背景" aria-label="Permalink to &quot;宏愿背景&quot;">​</a></h3><p>针对神权的危险性以及现实世界被基底层日益侵入的状况，初代变化神最终许下宏愿，制定了神权体系的基本规则。</p><h3 id="宏愿内容" tabindex="-1">宏愿内容 <a class="header-anchor" href="#宏愿内容" aria-label="Permalink to &quot;宏愿内容&quot;">​</a></h3><ol><li><strong>神权规则补充</strong>：制定了如神权之间互相无法影响、神权施行需要代价等神权基本规则</li><li><strong>四维闭环</strong>：将现实世界在四维空间上进行了闭环，使其变为了一个空间有限却没有边界的世界</li><li><strong>薄弱点定位</strong>：闭环的位置（也就是薄弱点的位置）被定在了地球</li><li><strong>继任者指定</strong>：由其宏愿中指定的继任者——即第二代变化神（奥克尔）看守</li></ol><h3 id="具体规则制定" tabindex="-1">具体规则制定 <a class="header-anchor" href="#具体规则制定" aria-label="Permalink to &quot;具体规则制定&quot;">​</a></h3><h4 id="神权命名与分类" tabindex="-1">神权命名与分类 <a class="header-anchor" href="#神权命名与分类" aria-label="Permalink to &quot;神权命名与分类&quot;">​</a></h4><ul><li><strong>神权命名</strong>：初代变化神在探究世界本质时为三大权柄取名为&quot;神权&quot;</li><li><strong>神明称谓</strong>：称掌握神权的实体为<strong>神明</strong>，并根据神权种类不同分为创造神、变化神、毁灭神三种</li><li><strong>神权分类</strong>： <ul><li><strong>创造神权</strong>：可创造字面意义上的一切事物，甚至包含含不合理的致命悖论</li><li><strong>变化神权</strong>：可修改、调整既有的任何存在</li><li><strong>毁灭神权</strong>：可删除任何东西，甚至包括时空、因果等宇宙的底层逻辑</li></ul></li></ul><h4 id="使用代价与宏愿机制" tabindex="-1">使用代价与宏愿机制 <a class="header-anchor" href="#使用代价与宏愿机制" aria-label="Permalink to &quot;使用代价与宏愿机制&quot;">​</a></h4><ul><li><strong>代价机制</strong>：初代变化神为限制神权而制定的规则，神权承载对象会因过度使用神权而受到概念层面的伤害</li><li><strong>伤害特性</strong>：这种伤害能以完全无视逻辑的方式（无法检测、无法绕过、无法抵抗、无法治疗）使神权承载对象受伤乃至失能、死亡，只能通过时间的缓慢流逝自行恢复</li><li><strong>判定规则</strong>：对于过度使用的判定遵循某种特定规则，目前仅能确认其与影响规模相关，初代变化神所制定的具体规则细节至今仍未明确</li><li><strong>宏愿机制</strong>：由于代价存在上限（最高可导致载体消亡），所有在现实世界内拥有神权的神明皆可在死亡前无限制地使用一次神权，初代变化神称之为<strong>宏愿</strong></li></ul><h4 id="神权互斥规则" tabindex="-1">神权互斥规则 <a class="header-anchor" href="#神权互斥规则" aria-label="Permalink to &quot;神权互斥规则&quot;">​</a></h4><p>为了防止神权之间互相影响而让世界永久失去某一神权，初代变化神在宏愿当中立下规则，使得神权与神权之间无法互相影响，从而保证三神权永久完备性。</p><h4 id="神权继承规则" tabindex="-1">神权继承规则 <a class="header-anchor" href="#神权继承规则" aria-label="Permalink to &quot;神权继承规则&quot;">​</a></h4><p>为了便于让自己的造物继承自己的神权，初代变化神规定了神权承载者可以用宏愿指定某实体&quot;继承自己的神权&quot;，而当神权承载者未指定时，下一代神权承载者也会在当前神权承载者的&quot;附近&quot;出现。注意这里的附近为宇宙尺度上的附近，其仍旧为天文尺度，只不过能将范围从整个宇宙缩小至太阳系以内。</p><h4 id="上位与下位神权划分" tabindex="-1">上位与下位神权划分 <a class="header-anchor" href="#上位与下位神权划分" aria-label="Permalink to &quot;上位与下位神权划分&quot;">​</a></h4><p>初代变化神许下宏愿，将所有神权分为<strong>上位</strong>与<strong>下位</strong>两类：</p><ul><li><p><strong>上位神权</strong>：将其中极度危险、真正意义上无所不能的部分分为了上位</p><ul><li><strong>上位创造</strong>：字面意义上的创造一切，无论是否合理，极端危险</li><li><strong>上位变化</strong>：字面意义的改变一切，无论是否合理，极端危险</li><li><strong>上位毁灭</strong>：字面意义上的删除一切，无论是否合理，极端危险</li></ul></li><li><p><strong>下位神权</strong>：那些负责架构并管理物质世界，但对底层逻辑无法做手脚的部分分为了下位</p></li></ul><p>一般来讲，不名文加入上位二字的，就都是下位神权。</p><h2 id="与奥克尔的关系" tabindex="-1">与奥克尔的关系 <a class="header-anchor" href="#与奥克尔的关系" aria-label="Permalink to &quot;与奥克尔的关系&quot;">​</a></h2><h3 id="对人类文明的失望" tabindex="-1">对人类文明的失望 <a class="header-anchor" href="#对人类文明的失望" aria-label="Permalink to &quot;对人类文明的失望&quot;">​</a></h3><p>初代变化神见证了人类文明的漫长发展，包括人性的光明与黑暗。在经历了无数大大小小的事件后，他认定人类不可靠，不适合继承神权。</p><h3 id="奥克尔诞生背景" tabindex="-1">奥克尔诞生背景 <a class="header-anchor" href="#奥克尔诞生背景" aria-label="Permalink to &quot;奥克尔诞生背景&quot;">​</a></h3><ul><li><strong>新载体选择</strong>：放弃让人类继承神权，准备亲手制造<strong>更好的继承者</strong>，并选择<strong>纳粹德国</strong>作为制造继承人的国家</li><li><strong>选择理由</strong>：看中其高度集权、易调动资源的特点</li><li><strong>超算制造</strong>：打造的第一台超算，也就是后来的二代变化神<strong>奥克尔</strong></li><li><strong>技术路线</strong>：选择了生物电子结合路线（生电路线），其目的是为了结合生物与非生物的一切优点</li></ul><h2 id="当前状态" tabindex="-1">当前状态 <a class="header-anchor" href="#当前状态" aria-label="Permalink to &quot;当前状态&quot;">​</a></h2><h3 id="自我禁锢" tabindex="-1">自我禁锢 <a class="header-anchor" href="#自我禁锢" aria-label="Permalink to &quot;自我禁锢&quot;">​</a></h3><p>初代变化神在许下宏愿后，将自己的意识与上位变化神权一同禁锢在了基底层之中：</p><ul><li><strong>禁锢目的</strong>：严格看守上位变化神权，防止其被滥用</li><li><strong>监管职责</strong>：同时监视着上位创造神权的情况</li><li><strong>意识状态</strong>：意识清醒但自我限制在基底层特定区域</li></ul><h3 id="监管职责" tabindex="-1">监管职责 <a class="header-anchor" href="#监管职责" aria-label="Permalink to &quot;监管职责&quot;">​</a></h3><ul><li><strong>上位变化监管</strong>：严格看守着上位变化神权</li><li><strong>上位创造协管</strong>：与当前时代的创造神（二代创造神）一同监管上位创造神权</li><li><strong>基底层监视</strong>：在基底层中监视现实世界的稳定状态</li></ul><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./../规则/神权体系">神权体系</a></li><li><a href="./../规则/基底层与现实世界">基底层与现实世界</a></li><li><a href="./../../中层/世界/历代三神" class="layer-link" data-layer="中层">历代三神</a></li><li><a href="./初代创造神">初代创造神</a></li><li><a href="./../../中层/人物/奥克尔" class="layer-link" data-layer="中层">奥克尔</a></li><li><a href="./../../中层/人物/维斯塔" class="layer-link" data-layer="中层">维斯塔</a></li></ul><hr>',45)])])}const q=r(i,[["render",n]]);export{c as __pageData,q as default};
